// ── fine funzioni di servizio ──
const { prompt_sistema, messaggio_utente, ...d } = $('Prepara la domanda per il piano').first().json;
const r = $input.first().json || {};
const TIPI = ['post', 'carosello', 'reel', 'storia'];

let piano = null;
let errore = '';
if (typeof r.statusCode !== 'number') errore = 'Claude non raggiungibile';
else if (r.statusCode !== 200) errore = 'Claude ha risposto con un errore (HTTP ' + r.statusCode + (r.body && r.body.error && r.body.error.message ? ': ' + r.body.error.message : '') + ')';
else if (r.body && r.body.stop_reason === 'refusal') errore = 'Claude non ha voluto preparare questo piano';
