// Controlla il piano di Claude: date dentro il mese, orari validi, numeri giusti, id unici.
// Prepara le righe per il Calendario, i messaggi per Telegram e la risposta del modulo.
// ── Funzioni di servizio (le stesse in tutti i nodi Code dei workflow 03 e 04) ──
const testo = (v) => (v === null || v === undefined ? '' : String(v)).trim();
const taglia = (v, n) => { const s = testo(v); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
// Telegram usa il "Markdown semplice": i caratteri _ * ` [ dei testi vanno neutralizzati,
// altrimenti Telegram rifiuta il messaggio. Dentro il *grassetto* non si mettono mai testi variabili.
const md = (v) => testo(v).replace(/\\/g, '/').replace(/([_*`[])/g, '\\$1');
const unisci = (righe) => righe.filter((r) => r !== null && r !== undefined && r !== false)
  .join('\n').replace(/\n{3,}/g, '\n\n').trim();
// «si/no» del foglio: accetta sì, si, yes, true, x… Se la cella è vuota vale «seVuoto».
const siNo = (v, seVuoto) => {
  const t = testo(v).toLowerCase();
  if (!t) return seVuoto;
  return ['si', 'sì', 'yes', 'true', 'vero', '1', 'x', 'ok'].includes(t);
};
const slug = (s) => testo(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9_-]+/g, '-').replace(/^-+|-+$/g, '') || 'senza-nome';
const due = (n) => String(n).padStart(2, '0');
const GIORNI = ['domenica', 'lunedì', 'martedì', 'mercoledì', 'giovedì', 'venerdì', 'sabato'];
const GIORNI_BREVI = ['dom', 'lun', 'mar', 'mer', 'gio', 'ven', 'sab'];
const MESI = ['gennaio', 'febbraio', 'marzo', 'aprile', 'maggio', 'giugno', 'luglio', 'agosto', 'settembre', 'ottobre', 'novembre', 'dicembre'];
const giornoSettimana = (anno, mese, giorno) => new Date(Date.UTC(anno, mese - 1, giorno)).getUTCDay();
const giorniNelMese = (anno, mese) => new Date(Date.UTC(anno, mese, 0)).getUTCDate();
// Oggi a Roma: { anno, mese, giorno, ore, minuti }
const oggiRoma = () => {
  const p = {};
  for (const x of new Intl.DateTimeFormat('it-IT', { timeZone: 'Europe/Rome', year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(new Date())) p[x.type] = x.value;
  return { anno: Number(p.year), mese: Number(p.month), giorno: Number(p.day), ore: Number(p.hour), minuti: Number(p.minute) };
};
// data_ora del Calendario → { anno, mese, giorno, ore, minuti, chiave: 'AAAA-MM-GG HH:MM', leggibile: 'ven 5/12 ore 19:00' } o null.
// Accetta il testo scritto dai workflow (2026-12-05 19:30), le date all'italiana e il numero seriale di Google Sheets.
const leggiDataOra = (v) => {
  let a; let me; let g; let o; let mi;
  if (typeof v === 'number' && isFinite(v)) {
    const t = new Date(Date.UTC(1899, 11, 30) + Math.round(v * 86400000));
    [a, me, g, o, mi] = [t.getUTCFullYear(), t.getUTCMonth() + 1, t.getUTCDate(), t.getUTCHours(), t.getUTCMinutes()];
  } else {
    const s = testo(v).replace(/\s+/g, ' ');
    let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})[ T](\d{1,2})[:.](\d{2})/);
    if (m) [a, me, g, o, mi] = [m[1], m[2], m[3], m[4], m[5]].map(Number);
    else {
      m = s.match(/^(\d{1,2})[/.-](\d{1,2})[/.-](\d{4}),? (\d{1,2})[:.](\d{2})/);
      if (!m) return null;
      [g, me, a, o, mi] = [m[1], m[2], m[3], m[4], m[5]].map(Number);
    }
  }
  if (!(me >= 1 && me <= 12 && g >= 1 && g <= giorniNelMese(a, me) && o >= 0 && o <= 23 && mi >= 0 && mi <= 59)) return null;
  return { anno: a, mese: me, giorno: g, ore: o, minuti: mi, chiave: `${a}-${due(me)}-${due(g)} ${due(o)}:${due(mi)}`,
    leggibile: `${GIORNI_BREVI[giornoSettimana(a, me, g)]} ${g}/${me} ore ${due(o)}:${due(mi)}` };
};
// La scheda del cliente dal foglio Clienti, con i campi nuovi già puliti.
const schedaCliente = (r) => ({
