// ── fine funzioni di servizio ──
const d = $input.first().json;
const c = d.cliente;
const p = d.periodo;
const k = d.conteggi;
const avvisi = [];

if (!d.ai_ok) {
  return [{ json: { ok: false, righe: [], messaggi: [
    unisci([`⚠️ *Piano non creato* · ${md(c.nome_locale)} · ${md(p.nome_mese)} ${p.anno}`, `Motivo: ${md(d.ai_errore)}.`,
      'Nel Calendario non è stato scritto niente: rimandate il modulo tra qualche minuto.']),
  ], messaggio_modulo: `Non sono riuscito a creare il piano: ${d.ai_errore}. Nel Calendario non è stato scritto niente: riprova tra qualche minuto.` } }];
}

const ZONE = ['piatti e drink', 'bancone', 'cucina', 'sala', 'esterno', 'staff', 'altro'];
const ORA_DI_RISERVA = { post: '12:30', carosello: '12:30', reel: '19:00', storia: '11:00' };
const GRUPPO = { reel: 'reel', post: 'foto', carosello: 'foto', storia: 'storie' };

// 1) Ogni contenuto: giorno dentro il mese, ora valida e ragionevole (06:00-23:30), idea presente.
const validi = [];
let fuoriMese = 0;
let orariCorretti = 0;
for (const x of d.contenuti_ai) {
  if (!(x.giorno >= p.giorno_inizio && x.giorno <= p.giorni)) { fuoriMese++; continue; }
  if (!testo(x.idea)) continue;
  let ora = testo(x.ora);
  const m = ora.match(/^(\d{1,2})[:.](\d{2})$/);
  const minuti = m ? Number(m[1]) * 60 + Number(m[2]) : -1;
  if (!m || Number(m[1]) > 23 || Number(m[2]) > 59 || minuti < 6 * 60 || minuti > 23 * 60 + 30) { ora = ORA_DI_RISERVA[x.tipo]; orariCorretti++; }
  else ora = `${due(Number(m[1]))}:${m[2]}`;
  const zona = ZONE.includes(testo(x.zona).toLowerCase()) ? testo(x.zona).toLowerCase() : 'altro';
  validi.push({ tipo: x.tipo, giorno: x.giorno, ora, idea: testo(x.idea), da_riprendere: testo(x.da_riprendere), zona,
    dal_vivo: x.tipo === 'storia' && x.dal_vivo === true, alias: Array.isArray(x.file) ? x.file.map((a) => testo(a).toUpperCase()) : [] });
}
if (fuoriMese) avvisi.push(`${fuoriMese} contenuti erano fuori dai giorni del mese: scartati`);
if (orariCorretti) avvisi.push(`${orariCorretti} orari non validi sostituiti con un orario standard`);

// 2) I numeri: se Claude ne propone di più tengo i primi in ordine di data, se ne propone meno lo segnalo.
validi.sort((a, b) => a.giorno - b.giorno || a.ora.localeCompare(b.ora));
const richiesti = { reel: k.reel, foto: k.foto, storie: k.storie };
const nomi = { reel: 'reel', foto: 'foto o caroselli', storie: 'storie' };
const tenuti = [];
for (const gruppo of ['reel', 'foto', 'storie']) {
  const delGruppo = validi.filter((x) => GRUPPO[x.tipo] === gruppo);
  if (delGruppo.length > richiesti[gruppo]) avvisi.push(`Claude ha proposto ${delGruppo.length} ${nomi[gruppo]} invece di ${richiesti[gruppo]}: tenuti i primi ${richiesti[gruppo]}`);
  if (delGruppo.length < richiesti[gruppo]) avvisi.push(`mancano ${richiesti[gruppo] - delGruppo.length} ${nomi[gruppo]} (aggiungeteli a mano)`);
  tenuti.push(...delGruppo.slice(0, richiesti[gruppo]));
}
tenuti.sort((a, b) => a.giorno - b.giorno || a.ora.localeCompare(b.ora));

// 3) Le regole del piano (si segnalano, non si correggono: il piano resta in «idea» e lo rivede il team).
const conta = (filtro) => { const n = {}; for (const x of tenuti.filter(filtro)) n[x.giorno] = (n[x.giorno] || 0) + 1; return n; };
const feedPerGiorno = conta((x) => x.tipo !== 'storia');
const storiePerGiorno = conta((x) => x.tipo === 'storia');
const doppiFeed = Object.keys(feedPerGiorno).filter((g) => feedPerGiorno[g] > 1);
const doppieStorie = Object.keys(storiePerGiorno).filter((g) => storiePerGiorno[g] > 1);
if (doppiFeed.length) avvisi.push(`più di un reel/post nello stesso giorno: ${doppiFeed.join(', ')} ${p.nome_mese}`);
if (doppieStorie.length) avvisi.push(`più di una storia nello stesso giorno: ${doppieStorie.join(', ')} ${p.nome_mese}`);
const nelleChiusure = tenuti.filter((x) => d.giorni_chiusura.includes(giornoSettimana(p.anno, p.mese, x.giorno)));
if (nelleChiusure.length) avvisi.push(`${nelleChiusure.length} contenuti cadono in un giorno di chiusura (${[...new Set(nelleChiusure.map((x) => x.giorno))].join(', ')} ${p.nome_mese}): spostateli`);
const giorniGiaUsati = new Set(d.gia_presenti.filter((x) => x.tipo !== 'storia').map((x) => x.giorno));
const sovrapposti = tenuti.filter((x) => x.tipo !== 'storia' && giorniGiaUsati.has(x.giorno));
if (sovrapposti.length) avvisi.push(`${sovrapposti.length} contenuti cadono in giorni che avevano già un post: ${[...new Set(sovrapposti.map((x) => x.giorno))].join(', ')}`);

// 3-bis) I file proposti da Claude: solo alias veri, ogni file una volta sola (vince il primo contenuto), il tipo giusto
// per il formato (reel 1 video, post 1 foto, storia 1 file, carosello 2-10 foto). Una storia con file non è «dal vivo».
const perAlias = {};
for (const f of d.inventario || []) perAlias[f.alias] = f;
const presi = new Set();
let fileScartati = 0;
let senzaRiprese = 0;
// i nomi dei file vanno nel brief, che il 04 passa a Claude: solo lettere, cifre e pochi segni, e corti
const nomeSicuro = (n) => taglia(testo(n).normalize('NFC').replace(/[^\p{L}\p{N} ._()-]+/gu, ' ').replace(/\s+/g, ' '), 40);
for (const x of tenuti) {
  const scelti = [];
  for (const a of x.alias) {
    const f = perAlias[a];
    if (!f || presi.has(a) || scelti.some((s) => s.alias === a)) { fileScartati++; continue; }
    const rapportoOk = !f.rapporto || (f.rapporto >= 0.79 && f.rapporto <= 1.92);
    if ((x.tipo === 'reel' && f.durata && (f.durata < 3 || f.durata > 90)) || (x.tipo === 'storia' && f.tipo === 'video' && f.durata > 60)
      || ((x.tipo === 'post' || x.tipo === 'carosello') && !rapportoOk)) { fileScartati++; continue; }
    const va = x.tipo === 'reel' ? f.tipo === 'video' && scelti.length < 1
      : x.tipo === 'post' ? f.tipo === 'foto' && scelti.length < 1
        : x.tipo === 'storia' ? scelti.length < 1
          : f.tipo === 'foto' && scelti.length < 10;
    if (!va) { fileScartati++; continue; }
    scelti.push(f);
  }
  if (x.tipo === 'carosello' && scelti.length < 2) { fileScartati += scelti.length; scelti.length = 0; }
  for (const f of scelti) presi.add(f.alias);
  x.file = scelti;
  if (x.file.length && x.tipo === 'storia') x.dal_vivo = false;
  // file proposti ma tutti scartati: «niente» da riprendere non basta più, la squadra deve sapere cosa girare
  if (x.alias.length && !x.file.length && (!testo(x.da_riprendere) || /^niente\.?$/i.test(testo(x.da_riprendere)))) {
    x.da_riprendere = 'da definire: i file proposti non andavano bene, scegliete cosa girare per questa idea';
