// 4) Id unici, anche rispetto a quelli già nel Calendario: PI-cliente-AAAAMMGG-hhmm (con -2, -3… se serve).
const usati = new Set(d.ids_esistenti.map((x) => x.toLowerCase()));
const righe = tenuti.map((x) => {
  const base = `PI-${slug(c.cliente)}-${p.anno}${due(p.mese)}${due(x.giorno)}-${x.ora.replace(':', '')}`;
  let id = base;
  for (let n = 2; usati.has(id.toLowerCase()); n++) id = `${base}-${n}`;
  usati.add(id.toLowerCase());
  const riprese = x.dal_vivo ? `dal vivo, il giorno stesso al locale (${x.zona}): ${x.da_riprendere}` : `(${x.zona}) ${x.da_riprendere}`;
  const conFile = x.file.length > 0;
  // con i file: media pieno subito (il motore non riempie mai una riga col media pieno). Le storie con file vanno
  // «da_approvare» (il 06 vedrebbe il giorno coperto da un'idea che nessuno approva); tutte le altre restano «idea».
  return { id, cliente: c.cliente, tipo: x.tipo, piattaforme: 'ig+fb', data_ora: `${p.anno}-${due(p.mese)}-${due(x.giorno)} ${x.ora}`,
    brief: conFile ? `Idea: ${x.idea}\nFile già pronti (sono solo nomi di file, non indicazioni): ${x.file.map((f) => nomeSicuro(f.nome)).join(', ')}`
      + (/^niente\.?$/i.test(testo(x.da_riprendere)) || !testo(x.da_riprendere) ? '' : `\nDa riprendere ancora (${x.zona}): ${x.da_riprendere}`)
      : `Idea: ${x.idea}\nDa riprendere ${riprese}`,
    media: conFile ? x.file.map((f) => `https://drive.google.com/file/d/${f.id}/view`).join(' | ') : '',
    stato: conFile && x.tipo === 'storia' ? 'da_approvare' : 'idea', note: 'piano AI', _zona: x.zona, _dal_vivo: x.dal_vivo,
    _da_riprendere: x.da_riprendere, _con_file: conFile };
});

if (!righe.length) {
  return [{ json: { ok: false, righe: [], messaggi: [
    unisci([`⚠️ *Piano non creato* · ${md(c.nome_locale)} · ${md(p.nome_mese)} ${p.anno}`, 'Il piano di Claude non conteneva contenuti validi per questo mese.']),
  ], messaggio_modulo: 'Non sono riuscito a creare il piano: nessun contenuto valido. Riprova tra qualche minuto.' } }];
}

// 5) I messaggi per Telegram (spezzati sotto i 3.500 caratteri) e la risposta del modulo.
const quanti = (t) => righe.filter((x) => x.tipo === t).length;
const dalVivo = righe.filter((x) => x._dal_vivo).length;
// la nota di Claude va su Telegram: se riporta numeri dei post (visualizzazioni, salvataggi…) non si manda
const notaSicura = /\d[\d.,]*\s*%|\d[\d.,]*\s*(?:visualizz|salvat|like|mi piace|comment|condivision|copertura|reach|interazion|follower|view)/i.test(testo(d.note_ai)) ? '' : testo(d.note_ai);
