const storieDaApprovare = righe.filter((x) => x._con_file && x.tipo === 'storia').length;
const fileLiberi = Math.max(0, (Number(d.liberi_totali) || (d.inventario || []).length) - presi.size);
const quando = (x) => { const g = Number(x.data_ora.slice(8, 10)); return `${GIORNI_BREVI[giornoSettimana(p.anno, p.mese, g)]} ${g}/${p.mese} ${x.data_ora.slice(11)}`; };
