  return { anno: a, mese: me, giorno: g, ore: o, minuti: mi, chiave: `${a}-${due(me)}-${due(g)} ${due(o)}:${due(mi)}`,
    leggibile: `${GIORNI_BREVI[giornoSettimana(a, me, g)]} ${g}/${me} ore ${due(o)}:${due(mi)}` };
};
// La scheda del cliente dal foglio Clienti, con i campi nuovi già puliti.
const schedaCliente = (r) => ({
  cliente: testo(r.cliente),
  nome_locale: testo(r.nome_locale) || testo(r.cliente),
  attivo: siNo(r.attivo, false),
  tono_di_voce: testo(r.tono_di_voce),
  orari: testo(r.orari),
  link_prenotazione: testo(r.link_prenotazione),
  telefono: testo(r.telefono),
  indirizzo: testo(r.indirizzo),
  link_menu: testo(r.link_menu),
  regole: testo(r.regole_risposte),
  id_luogo: testo(r.id_luogo),
  account_da_taggare: testo(r.account_da_taggare),
  hashtag_fissi: testo(r.hashtag_fissi),
  note_piano: testo(r.note_piano),
  approvazione_testi: siNo(r.approvazione_testi, true), // vuoto = si: nel dubbio decide una persona
  esempi_didascalie: testo(r.esempi_didascalie),
  menu_testo: testo(r.menu_testo),
});
// Il testo che arriva dal foglio è un DATO: non deve poter aprire o chiudere i tag del prompt.
const datoPulito = (v) => testo(v).replace(/</g, '‹').replace(/>/g, '›');
// «esempi_didascalie»: da 3 a 5 didascalie separate da una riga con solo «---». Ne tengo al massimo 5.
const esempiDiStile = (v) => testo(v).split(/\r?\n\s*-{3,}\s*(?:\r?\n|$)/).map((x) => taglia(x, 1200)).filter(Boolean).slice(0, 5);
// Le righe della scheda Esempi di un cliente, le più recenti prima (per data, poi per posizione nel foglio).
const esempiDelCliente = (righe, cliente, fonti, quanti) => righe
  .filter((r) => r && testo(r.cliente).toLowerCase() === testo(cliente).toLowerCase() && fonti.includes(testo(r.fonte).toLowerCase()) && testo(r.testo))
  .map((r) => ({ data: leggiDataOra(r.data_ora), riga: Number(r.row_number) || 0, tipo: testo(r.tipo).toLowerCase(), fonte: testo(r.fonte).toLowerCase(),
    testo: taglia(r.testo, 800), metriche: taglia(r.metriche, 200) }))
  .sort((a, b) => ((b.data && b.data.chiave) || '').localeCompare((a.data && a.data.chiave) || '') || b.riga - a.riga)
  .slice(0, quanti)
  .map(({ data, riga, ...x }) => ({ ...x, data_ora: data ? data.chiave : '' }));
// ── fine funzioni di servizio ──
// Due cose per il piano, senza nessuna lettura da Meta:
// 1) lo storico del cliente: i pubblicati degli ultimi 90 giorni (Calendario) e quali erano tra i migliori (Esempi, dal 09);
// 2) l'inventario dei file in «Da programmare» non ancora usati in nessuna riga del Calendario, con un alias F1, F2…
// Gli id Drive non vanno mai a Claude: solo gli alias. Link, metriche e testi dei post non vanno mai su Telegram.
const d = $('Guarda il calendario').first().json;
const cliente = d.cliente.cliente;
const cart = $('Cartella del cliente').first().json;
const dp = $('Da programmare').first().json;
const elenco = $('Elenca i file').first().json || {}; // non $input: arriva dall'Archivio
const calendario = $('Leggi il calendario').all().map((i) => i.json || {}).filter((r) => r && r.row_number !== undefined);
const esempi = $('Leggi gli esempi').all().map((i) => i.json || {}).filter((r) => r && r.row_number !== undefined);
const archivio = $('Leggi Archivio file').all().map((i) => i.json || {}).filter((r) => r && r.row_number !== undefined && testo(r.file_id));

// --- 1) storico ---
const normLink = (v) => testo(v).replace(/[?#].*$/, '').replace(/\/+$/, '').toLowerCase();
const migliori = new Set(esempi.filter((r) => testo(r.cliente).toLowerCase() === cliente.toLowerCase() && testo(r.fonte).toLowerCase() === 'migliori_post')
  .map((r) => normLink(r.id_contenuto)).filter((l) => /^https?:\/\//.test(l)));
const o = oggiRoma();
const oggiMs = Date.UTC(o.anno, o.mese - 1, o.giorno);
const pubblicati = calendario.filter((r) => testo(r.cliente) === cliente && testo(r.stato).toLowerCase() === 'pubblicato')
  .map((r) => ({ r, d: leggiDataOra(r.data_ora) || leggiDataOra(r.pubblicato_il) }))
  .filter((x) => x.d && oggiMs - Date.UTC(x.d.anno, x.d.mese - 1, x.d.giorno) <= 90 * 86400000)
  .sort((a, b) => b.d.chiave.localeCompare(a.d.chiave));
const idea = (b) => { const m = testo(b).match(/Idea:\s*([^\n]+)/i); return taglia(m ? m[1] : testo(b).split('\n')[0], 120); };
const feed = pubblicati.filter((x) => testo(x.r.tipo).toLowerCase() !== 'storia');
const sceltiFeed = [...feed.filter((x) => migliori.has(normLink(x.r.link_ig))), ...feed.filter((x) => !migliori.has(normLink(x.r.link_ig)))].slice(0, 30)
  .sort((a, b) => b.d.chiave.localeCompare(a.d.chiave));
const storie = pubblicati.filter((x) => testo(x.r.tipo).toLowerCase() === 'storia');
const fasce = {};
for (const x of storie) { const f = x.d.ore < 11 ? 'mattina' : x.d.ore < 15 ? 'pranzo' : x.d.ore < 18 ? 'pomeriggio' : 'sera'; fasce[f] = (fasce[f] || 0) + 1; }
const riassuntoStorie = storie.length ? `${storie.length} storie pubblicate (${Object.entries(fasce).map(([f, n]) => `${f} ${n}`).join(', ')})` : '';
const storico = sceltiFeed.map((x) => ({
  quando: `${GIORNI_BREVI[giornoSettimana(x.d.anno, x.d.mese, x.d.giorno)]} ${due(x.d.ore)}:${due(x.d.minuti)}`,
  tipo: testo(x.r.tipo).toLowerCase(), migliore: migliori.has(normLink(x.r.link_ig)), idea: idea(x.r.brief) }));
const nMigliori = pubblicati.filter((x) => migliori.has(normLink(x.r.link_ig))).length;

// --- 2) inventario ---
const idDaLink = (voce) => {
  const t = testo(voce);
  const m = t.match(/\/d\/([A-Za-z0-9_-]{10,})/) || t.match(/[?&]id=([A-Za-z0-9_-]{10,})/);
  if (m) return m[1];
  return /^[A-Za-z0-9_-]{10,}$/.test(t) ? t : '';
};
const usati = new Set();
for (const r of calendario) for (const c of [r.media, r.copertina]) for (const v of testo(c).split('|')) { const id = idDaLink(v); if (id) usati.add(id); }
const md5Usati = new Set(archivio.filter((a) => usati.has(testo(a.file_id)) && /^[0-9a-f]{32}$/i.test(testo(a.md5))).map((a) => testo(a.md5).toLowerCase()));
const descr = {};
for (const a of archivio) if (testo(a.descrizione) && testo(a.descrizione) !== 'senza miniatura') descr[testo(a.file_id)] = testo(a.descrizione);
const file = Array.isArray(elenco.files) ? elenco.files : [];
for (const f of file) if (usati.has(f.id) && /^[0-9a-f]{32}$/i.test(testo(f.md5Checksum))) md5Usati.add(testo(f.md5Checksum).toLowerCase());
const formato = (f) => {
  const mime = testo(f.mimeType).toLowerCase().split(';')[0].trim();
  if (/-copertina\.jpe?g$/i.test(testo(f.name))) return ''; // copertine dei reel: non sono foto da pubblicare
  if (['image/jpeg', 'image/jpg', 'image/pjpeg'].includes(mime)) return 'foto';
  if (['video/mp4', 'video/quicktime'].includes(mime)) return 'video';
  if (mime === '' || mime === 'application/octet-stream') { const e = testo(f.name).toLowerCase().split('.').pop(); return ['jpg', 'jpeg'].includes(e) ? 'foto' : ['mp4', 'mov'].includes(e) ? 'video' : ''; }
  return '';
};
const MAX_FOTO_BYTE = 8 * 1024 * 1024;
const MAX_FILE = Math.max(1, Number($('Config').first().json.MAX_FILE_PIANO) || 150);
const md5Visti = new Set();
const tuttiLiberi = file.filter((f) => formato(f) && !usati.has(f.id) && !md5Usati.has(testo(f.md5Checksum).toLowerCase())
  && !(formato(f) === 'foto' && Number(f.size) > MAX_FOTO_BYTE))
  .sort((a, b) => testo(b.modifiedTime).localeCompare(testo(a.modifiedTime)))
  .filter((f) => { const m = testo(f.md5Checksum).toLowerCase(); if (!/^[0-9a-f]{32}$/.test(m)) return true; if (md5Visti.has(m)) return false; md5Visti.add(m); return true; });
const liberi = tuttiLiberi.slice(0, MAX_FILE);
const orient = (w, h) => (!w || !h ? 'misure non lette' : w / h < 0.95 ? 'verticale' : w / h > 1.05 ? 'orizzontale' : 'quadrata');
const inventario = liberi.map((f, i) => {
  const im = f.imageMediaMetadata || {};
  const vm = f.videoMediaMetadata || {};
  let w = Number(im.width || vm.width) || 0;
  let h = Number(im.height || vm.height) || 0;
  if ([1, 3].includes(Number(im.rotation))) [w, h] = [h, w];
  const durata = Number(vm.durationMillis) > 0 ? Math.round(Number(vm.durationMillis) / 1000) : 0;
  return { alias: `F${i + 1}`, id: f.id, nome: testo(f.name), tipo: formato(f), w, h, orientamento: orient(w, h), durata,
    rapporto: w && h ? Math.round((w / h) * 100) / 100 : 0,
    descrizione: taglia(descr[f.id] || testo(f.name).replace(/\.[^.]+$/, ''), 160), data: testo(f.modifiedTime).slice(0, 10) };
});
let stato = 'ok';
let avviso = '';
if (!cart.cartella_id) { stato = 'senza_cartella'; avviso = 'nella scheda Clienti manca cartella_drive: piano senza i file già pronti'; }
else if (dp.errore_drive || elenco.error) { stato = 'errore'; avviso = 'Drive non ha risposto: piano senza i file già pronti'; }
else if (!dp.dp_id) { stato = 'senza_cartella'; avviso = 'nella cartella del cliente non c\'è «Da programmare»: piano senza i file già pronti'; }
return [{ json: { storico, riassunto_storie: riassuntoStorie, storico_conteggi: { pubblicati: pubblicati.length, migliori: nMigliori },
  inventario, liberi_totali: tuttiLiberi.length, inventario_stato: stato, inventario_avviso: avviso, file_totali_in_cartella: file.length } }];
